INSERT INTO programs (id, name, level, jurisdiction, city_scope, category, summary, benefit, eligibility_text, apply_url, source_url, source_label, source_snippet, interest_tags, audience_tags, housing_scope, min_age, max_age, income_targeted, requires_children, requires_disability, requires_veteran, requires_caregiver, embedding_json, last_checked, active) VALUES ('calable', 'CalABLE Disability Savings Account', 'state', 'California', 'sunnyvale,cupertino', 'other', 'CalABLE offers tax-advantaged savings for disability-related expenses while protecting eligibility for many means-tested public benefits within program limits.', 'Tax-free qualified withdrawals and the ability to save beyond ordinary SSI resource limits under applicable rules.', 'For people whose qualifying disability began before age 46 and who meet federal ABLE eligibility criteria.', 'https://calable.ca.gov/', 'https://calable.ca.gov/', 'California State Treasurer''s Office', 'CalABLE lets eligible people with disabilities save and invest for qualified expenses without automatically losing public benefits.', 'disability,savings,financial,ssi,expenses', 'disability', 'any', NULL, NULL, 0, 0, 1, 0, 0, '[0.055792,0,0,-0.092057,0.184113,-0.27896,0.07253,-0.036265,0.07253,-0.07253,0.092057,0,0,-0.036265,0,-0.055792,0.167376,-0.092057,0,-0.07253,0,-0.055792,0.036265,0,0.036265,0,0.092057,0,0.111584,-0.036265,0,0,0,0,0.092057,-0.07253,0.128322,0,0.147849,0,0,0,0.055792,0,0.055792,-0.036265,0,-0.036265,0.055792,0,0.036265,0,0.036265,0,0.055792,-0.036265,0.092057,-0.036265,0.111584,-0.27896,0.111584,0,0.167376,-0.036265,0,-0.036265,0,0,0,-0.111584,0.092057,-0.07253,0.055792,-0.092057,0,-0.164586,0,-0.055792,0.167376,-0.055792,0,-0.036265,0,-0.055792,0,-0.055792,0.055792,-0.036265,0,0,0.07253,-0.147849,0.371017,-0.036265,0.147849,-0.111584,0.055792,-0.036265,0,0,0.036265,-0.128322,0.07253,0,0,0,0.092057,-0.147849,0.055792,0,0.055792,0,0.223168,0,0.07253,0,0.036265,-0.111584,0,0,0.07253,0,0,0,0.111584,0,0.0362