INSERT INTO programs (id, name, level, jurisdiction, city_scope, category, summary, benefit, eligibility_text, apply_url, source_url, source_label, source_snippet, interest_tags, audience_tags, housing_scope, min_age, max_age, income_targeted, requires_children, requires_disability, requires_veteran, requires_caregiver, embedding_json, last_checked, active) VALUES ('california-disability-insurance', 'California Disability Insurance', 'state', 'California', 'sunnyvale,cupertino', 'health', 'Disability Insurance provides short-term wage replacement to eligible workers unable to work because of a non-work-related illness, injury, pregnancy, or childbirth.', 'Partial wage replacement for an eligible disability period, potentially up to 52 weeks.', 'For qualifying workers with wage loss who paid into State Disability Insurance and meet medical-certification and claim requirements.', 'https://edd.ca.gov/en/disability/general_information/', 'https://edd.ca.gov/en/disability/general_information/', 'California Employment Development Department', 'EDD administers Disability Insurance as part of California State Disability Insurance.', 'disability,health,income,wage replacement,pregnancy', 'worker,disability,pregnant', 'any', NULL, NULL, 0, 0, 1, 0, 0, '[0.076696,-0.030214,0.030214,-0.030214,0.092965,-0.309109,0.046483,-0.092965,0,0,0.030214,0,0,0,0.030214,-0.169661,0.092965,-0.030214,0.090641,0,0.030214,0,0,0,0,0,0.123179,-0.030214,0.030214,-0.046483,0.046483,-0.030214,0.046483,-0.216144,0,-0.046483,0.232413,0,0.139448,-0.232413,0.030214,0,0,0,0.123179,0,0.030214,0,0.046483,0,0,0,0.030214,-0.030214,0.030214,-0.046483,0.076696,0,0,-0.278896,0,-0.030214,0.030214,0,0.090641,-0.046483,0.030214,-0.060427,0.030214,0,0.046483,-0.139448,0.030214,-0.216144,0.090641,0,0,-0.030214,0,-0.076696,0,0,0.030214,-0.030214,0.030214,-0.046483,0.046483,-0.123179,0.030214,0,0.030214,-0.046483,0.478771,0,0.137124,0,0.092965,0,0,0,0,0,0.092965,-0.030214,0.076696,-0.046483,0.076696,-0.030214,0.030214