INSERT INTO programs (id, name, level, jurisdiction, city_scope, category, summary, benefit, eligibility_text, apply_url, source_url, source_label, source_snippet, interest_tags, audience_tags, housing_scope, min_age, max_age, income_targeted, requires_children, requires_disability, requires_veteran, requires_caregiver, embedding_json, last_checked, active) VALUES ('california-paid-family-leave', 'California Paid Family Leave', 'state', 'California', 'sunnyvale,cupertino', 'family', 'Paid Family Leave provides short-term wage replacement when eligible workers care for a seriously ill family member, bond with a new child, or handle a qualifying military event.', 'Up to eight weeks of partial wage replacement in a 12-month period.', 'For qualifying workers with wage loss who paid into State Disability Insurance and meet timing, work, care, bonding, or military-event requirements.', 'https://edd.ca.gov/en/disability/faq_pfl_benefits_payments/', 'https://edd.ca.gov/en/disability/faq_pfl_benefits_payments/', 'California Employment Development Department', 'EDD states that Paid Family Leave may provide up to eight weeks of partial pay for qualifying family leave.', 'family,caregiver,baby,leave,income,military', 'worker,caregiver,parent,military family', 'any', NULL, NULL, 0, 0, 0, 0, 0, '[0,0,0.036275,-0.036275,0.167423,-0.111616,0.036275,-0.203699,0,0,0.036275,0,0.036275,-0.147891,0.07255,-0.055808,0.147891,-0.092083,0.147891,0,0.07255,0,0.259506,0,0.036275,-0.055808,0.111616,-0.036275,0.036275,0,0.055808,-0.111616,0.092083,-0.036275,0,-0.055808,0.092083,-0.036275,0.055808,-0.092083,0,-0.334847,0.036275,0,0.111616,0,0.092083,0,0.111616,-0.036275,0.036275,0,0,0,0.07255,-0.111616,0.036275,-0.07255,0,-0.055808,0.092083,-0.036275,0,0,0.203699,-0.055808,0.036275,-0.055808,0.036275,-0.07255,0,-0.111616,0,-0.203699,0,-0.036275,0.259506,-0.1451,0,-0.055808,0.07255,0,0,-0.055808,0.036275,-0.092083,0.055808,-0.184166,0.036275,-0.07255,0,-0.036275,0.092083,-0.055808,0.164633,0,0.09