INSERT INTO programs (id, name, level, jurisdiction, city_scope, category, summary, benefit, eligibility_text, apply_url, source_url, source_label, source_snippet, interest_tags, audience_tags, housing_scope, min_age, max_age, income_targeted, requires_children, requires_disability, requires_veteran, requires_caregiver, embedding_json, last_checked, active) VALUES ('federal-ssi', 'Supplemental Security Income', 'federal', 'United States', 'sunnyvale,cupertino', 'other', 'SSI provides monthly payments to eligible people with limited income and resources who are disabled, blind, or age 65 or older.', 'Monthly federal cash payments, sometimes with a state supplement.', 'For people who meet age or disability, income, resource, residence, and citizenship or qualifying-noncitizen rules.', 'https://www.ssa.gov/apply/ssi', 'https://www.ssa.gov/apply/ssi', 'Social Security Administration', 'SSA accepts SSI applications for eligible adults and children with limited income and resources.', 'cash,disability,senior,income,ssi', 'senior,disability,blind,low income', 'any', NULL, NULL, 1, 0, 0, 0, 0, '[0.03698,-0.113785,0,-0.03698,0.264551,-0.22757,0.07396,-0.03698,0,0,0.03698,0,0.03698,0,0.03698,-0.284463,0.056893,0,0.03698,0,0.110941,-0.03698,0,0,0.03698,0,0.093873,0,0.113785,0,0,-0.03698,0.03698,-0.093873,0.056893,0,0.056893,-0.130853,0.22757,0,0.03698,-0.07396,0,-0.03698,0,0,0,0,0.056893,0,0.03698,0,0.113785,0,0.113785,-0.03698,0.07396,0,0,-0.321443,0,0,0.113785,0,0.03698,0,0,0,0.07396,0,0,-0.03698,0,0,0,0,0,-0.056893,0,-0.204813,0,0,0.113785,0,0,-0.224726,0.170678,0,0.03698,0,0,0,0.22757,-0.07396,0.284463,-0.07396,0.056893,-0.170678,0,0,0,0,0.07396,0,0.03698,-0.113785,0,-0.03698,0.056893,0,0.113785,0,0.093873,0,0.093873,-0.093873,0.130853,-0.113785,0.093873,0,0.03698,0,0,0,0,-0.03698,0,-0.22757]', '2026-10-23', 1);
INSERT INTO programs (id, name, level, jurisdiction, city_scope, category, summary, benefit, eligibility_text, apply_url, source_url, source_label, source_snippet, interest_tags, audience_tags, housing_scope, min_age, max_age, income_targeted, requires_children, requires_disability, requires_veteran, requires_caregiver, embedding_json, last_checked, active) VALUES ('federal-medicare-savings-programs', 'Medicare Savings Programs', 'federal', 'United States', 'sunnyvale,cupertino', 'health', 'Medicare Savings Programs are state-run programs that can help eligible people with limited income and resources pay Medicare Part A and Part B costs.', 'Help with Medicare Part A or Part B premiums and, depending on the program, deductibles, coinsurance, and copayments.', 'Applicants generally must have Medicare and meet the income, resource, and other rules for one of four programs: QMB, SLMB, QI, or QDWI. California makes the final eligibility decision, and limits may change each year.', 'https://www.medicare.gov/basics/costs/help/medicare-savings-programs', 'https://www.medicare.gov/basics/costs/help/medicare-savings-programs', 'Medicare.gov', 'Medicare explains the four Medicare Savings Programs, the costs each may cover, current qualification guidance, and how to contact the state to apply.', 'medicare,medicare savings program,msp,part a,part b,premium,deductible,coinsurance,copay,health,medical', 'medicare,senior,disability,worker,low income', 'any', NULL, NULL, 1, 0, 0, 0, 0, '[0.052122,-0.092216,0,0,0.080188,-0.080188,0.066155,-0.026061,0,-0.040094,0,-0.026061,0.052122,0,0,-0.120281,0.066155,-0.066155,0,-0.026061,0.266624,-0.026061,0,-0.066155,0.026061,0,0.026061,0,0.160375,-0.026061,0.066155,-0.026061,0.026061,-0.507186,0,-0.052122,0.026061,-0.106248,0.306717,-0.15837,0.266624,0,0.026061,-0.052122,0.066155,0,0,0,0.026061,0,0.026061,0,0.066155,-0.026061,0.118277,-0.146342,0.026061,-0.026061,0,-0.118277,0.052122,-0.040094,0.092216,-0.040094,0,-0.106248,0,0,0.026061,-0.040