INSERT INTO programs (id, name, level, jurisdiction, city_scope, category, summary, benefit, eligibility_text, apply_url, source_url, source_label, source_snippet, interest_tags, audience_tags, housing_scope, min_age, max_age, income_targeted, requires_children, requires_disability, requires_veteran, requires_caregiver, embedding_json, last_checked, active) VALUES ('federal-medicare-part-d-extra-help', 'Medicare Part D Extra Help', 'federal', 'United States', 'sunnyvale,cupertino', 'health', 'Extra Help lowers Medicare Part D prescription-drug costs for eligible people with limited income and resources.', 'Help paying Medicare drug-plan premiums, deductibles, coinsurance, copayments, and other Part D costs; the Part D late-enrollment penalty is waived while receiving Extra Help.', 'Eligibility generally requires Medicare and meeting current income and resource rules. People receiving full Medicaid, help with Part B premiums through a Medicare Savings Program, or SSI may qualify automatically; others can apply through Social Security.', 'https://www.ssa.gov/medicare/part-d-extra-help', 'https://www.medicare.gov/basics/costs/help/drug-costs', 'Medicare.gov and Social Security Administration', 'Medicare and Social Security explain who receives Extra Help automatically, who should apply, the costs it may reduce, and the online application process.', 'medicare,part d,extra help,low income subsidy,lis,prescription,drug costs,pharmacy,premium,deductible,copay', 'medicare,senior,disability,low income,prescription drugs', 'any', NULL, NULL, 1, 0, 0, 0, 0, '[0,-0.132663,0,0,0.066332,-0.144724,0.066332,0,0.026131,0,0,0,0.052261,0,0,-0.080402,0.040201,-0.146734,0.080402,-0.026131,0.267337,-0.066332,0.040201,-0.040201,0.066332,0,0.026131,0,0.040201,-0.026131,0.040201,-0.026131,0.026131,-0.480402,0.026131,-0.104523,0,-0.146734,0.160804,-0.092462,0.052261,-0.026131,0,-0.078392,0,-0.146734,0,-0.120603,0.052261,0,0.066332,0,0.118593,-0.026131,0.026131,-0.106533,0.026131,-0.052261,0.