INSERT INTO programs (id, name, level, jurisdiction, city_scope, category, summary, benefit, eligibility_text, apply_url, source_url, source_label, source_snippet, interest_tags, audience_tags, housing_scope, min_age, max_age, income_targeted, requires_children, requires_disability, requires_veteran, requires_caregiver, embedding_json, last_checked, active) VALUES ('federal-ssdi', 'Social Security Disability Insurance', 'federal', 'United States', 'sunnyvale,cupertino', 'other', 'SSDI pays monthly benefits to eligible workers whose qualifying disability prevents substantial work and who have sufficient Social Security work history.', 'Monthly disability payments based on the worker''s earnings record.', 'For people who meet Social Security''s disability standard and insured-work-credit requirements; waiting periods and other rules may apply.', 'https://www.ssa.gov/disability/disability.html', 'https://www.ssa.gov/disability/disability.html', 'Social Security Administration', 'SSA explains online and phone application paths for Social Security disability benefits.', 'disability,cash,income,work,ssdi', 'worker,disability', 'any', NULL, NULL, 0, 0, 1, 0, 0, '[0,-0.03127,0,-0.079377,0.192429,-0.288644,0.158754,-0.03127,0,0,0,-0.03127,0.03127,-0.079377,0.079377,-0.096215,0.048107,0,0,-0.03127,0.03127,0,0,-0.03127,0,0,0.06254,-0.03127,0.048107,-0.03127,0,0,0,-0.125079,0,0,0.048107,0,0.192429,-0.079377,0.048107,-0.03127,0,0,0.048107,0,0,0,0.048107,-0.048107,0,0,0.03127,0,0.190024,-0.03127,0,-0.06254,0.048107,-0.512344,0.03127,0,0.03127,0,0.03127,-0.048107,0.048107,-0.06254,0,0,0,0,0.048107,0,0.03127,0,0.079377,0,0,0,0.048107,-0.03127,0.192429,-0.048107,0,-0.096215,0.048107,-0.127485,0,-0.03127,0,0,0.351184,0,0.048107,-0.127485,0.240537,-0.03127,0,-0.03127,0.03127,-0.06254,0.03127,-0.06254,0,-0.03127,0.03127,0,0,0,0.079377,0,0.048107,-0.03127,0,0,0.079377,-0.127485,0.03127,0,0.03127,0,0,-0.079377,0.03127,0,0,-0.288644]', '2026-10-23', 1);
INSERT INTO programs (id, name, level, jurisdiction, city_scope, category, summary, benefit, eligibility_text, apply_url, source_url, source_label, source_snippet, interest_tags, audience_tags, housing_scope, min_age, max_age, income_targeted, requires_children, requires_disability, requires_veteran, requires_caregiver, embedding_json, last_checked, active) VALUES ('federal-va-disability', 'VA Disability Compensation', 'federal', 'United States', 'sunnyvale,cupertino', 'veterans', 'VA disability compensation provides tax-free monthly payments for qualifying illnesses or injuries caused or worsened by active military service.', 'Tax-free monthly compensation based on the VA disability rating and eligible dependents.', 'For eligible Veterans or service members with a service-connected condition and qualifying discharge or service history; evidence is required.', 'https://www.va.gov/disability/how-to-file-claim/', 'https://www.va.gov/disability/how-to-file-claim/', 'U.S. Department of Veterans Affairs', 'VA provides online, mail, in-person, fax, and accredited-representative paths for disability claims.', 'veteran,military,disability,cash,va', 'veteran,active duty,disability', 'any', NULL, NULL, 0, 0, 0, 1, 0, '[0,-0.030215,0,-0.030215,0.339339,-0.323069,0,0,0,-0.06043,0.030215,0,0.046485,0,0.0767,0,0.139454,0,0,0,0.232424,-0.046485,0.216154,-0.030215,0,-0.106915,0.0767,0,0.0767,0,0.030215,0,0.046485,0,0,-0.06043,0.046485,-0.092969,0.139454,0,0,0,0,-0.030215,0,-0.030215,0.06043,-0.092969,0.1534,-0.06043,0.030215,0,0.090645,0,0.092969,-0.046485,0,0,0.092969,-0.232424,0,-0.030215,0.046485,0,0.030215,-0.030215,0.030215,-0.030215,0,0,0.030215,0,0.030215,0,0,0,0.030215,-0.030215,0.030215,-0.046485,0.139454,-0.046485,0.046485,-0.030215,0,0,0,-0.06043,0.030215,-0.030215,0,-0.183615,0.262639,-0.06043,0.092969,-0.278908,0,0,0,0,0.216154,0,0.030215,0,0,-0.046485,0,0,0,0,0,-0.046485,0.092969,0,0.030215,-0.030215,0.046485,0,0.030215,0,0.278908,0,0.030215,0,0.090645,0,0.030215,-0.2