INSERT INTO programs (id, name, level, jurisdiction, city_scope, category, summary, benefit, eligibility_text, apply_url, source_url, source_label, source_snippet, interest_tags, audience_tags, housing_scope, min_age, max_age, income_targeted, requires_children, requires_disability, requires_veteran, requires_caregiver, embedding_json, last_checked, active) VALUES ('federal-va-health-care', 'VA Health Care', 'federal', 'United States', 'sunnyvale,cupertino', 'veterans', 'VA health care offers eligible Veterans preventive, primary, specialty, mental-health, and other covered services.', 'VA health coverage and access to covered care, with copays based on eligibility and priority group.', 'Generally for eligible Veterans with qualifying active-duty service and discharge status; service history, disability, income, and other factors may affect enrollment.', 'https://www.va.gov/health-care/about-va-health-benefits/', 'https://www.va.gov/health-care/about-va-health-benefits/', 'U.S. Department of Veterans Affairs', 'VA explains health-care benefits and application options for potentially eligible Veterans.', 'veteran,military,health,medical,insurance,va', 'veteran,active duty', 'any', NULL, NULL, 0, 0, 0, 1, 0, '[0,-0.111075,0.027245,-0.027245,0,-0.041915,0.06916,0,0,-0.041915,0,0,0.041915,-0.05449,0,-0.209576,0.041915,-0.027245,0,0,0.236821,0,0.167661,-0.027245,0,0,0,-0.041915,0,-0.027245,0,0,0,-0.419153,0,-0.081735,0.111075,-0.125746,0.236821,-0.305982,0,-0.027245,0.027245,-0.027245,0,-0.05449,0,-0.234726,0.041915,0,0,0,0.06916,-0.096405,0.027245,-0.06916,0,0,0.027245,-0.06916,0,0,0.027245,0,0,-0.027245,0,-0.027245,0.027245,0,0,0,0.027245,-0.05449,0.081735,0,0.125746,-0.027245,0.041915,-0.06916,0.041915,-0.13832,0,0,0.05449,0,0,0,0,-0.041915,0.027245,-0.027245,0.293407,0,0.06916,-0.041915,0.027245,-0.05449,0,0,0.083831,0,0,0,0,-0.125746,0.041915,-0.041915,0,-0.096405,0,-0.041915,0.083831,0,0,-0.027245,0.041915,-0.083831,0,0,0.404482,0,0.05449,0,0.081735,0,0,-0.06916]',