INSERT INTO programs (id, name, level, jurisdiction, city_scope, category, summary, benefit, eligibility_text, apply_url, source_url, source_label, source_snippet, interest_tags, audience_tags, housing_scope, min_age, max_age, income_targeted, requires_children, requires_disability, requires_veteran, requires_caregiver, embedding_json, last_checked, active) VALUES ('federal-va-pension', 'VA Veterans Pension', 'federal', 'United States', 'sunnyvale,cupertino', 'veterans', 'VA pension provides monthly payments to some wartime Veterans with limited income and net worth who meet age or disability rules.', 'Monthly pension payment based on income, net worth, dependents, and additional care needs.', 'For qualifying wartime Veterans with acceptable discharge, required service, income and net-worth limits, plus age 65 or qualifying disability or care status.', 'https://www.va.gov/pension/eligibility/', 'https://www.va.gov/pension/eligibility/', 'U.S. Department of Veterans Affairs', 'VA Pension supports qualifying wartime Veterans who meet service, financial, age, or disability requirements.', 'veteran,military,senior,disability,cash,pension', 'veteran,senior,disability,low income', 'any', NULL, NULL, 1, 0, 0, 1, 0, '[0.029688,-0.045674,0,-0.029688,0.166709,-0.182695,0.029688,0,0.029688,-0.029688,0,0,0,0,0,-0.166709,0.075362,-0.029688,0,0,0.30373,0,0.287744,0,0.029688,-0.258056,0.029688,0,0.166709,0,0.059376,-0.137021,0.075362,-0.029688,0,0,0.137021,-0.258056,0.182695,0,0.059376,0,0.089064,-0.089064,0.029688,0,0.029688,0,0.121035,-0.029688,0.029688,0,0,0,0.091347,-0.075362,0.059376,-0.059376,0.075362,-0.182695,0,0,0,0,0,-0.029688,0,0,0.059376,-0.105049,0,0,0,-0.059376,0,-0.029688,0.091347,0,0,-0.045674,0.045674,0,0.045674,-0.029688,0,-0.091347,0.137021,-0.059376,0.166709,-0.045674,0,0,0.182695,-0.029688,0.182695,-0.118751,0.045674,-0.091347,0,0,0.045674,0,0,0,0,-0.091347,0.029688,0,0.029688,0,0,-0.045674,0.029688,-0.091347,0,-0.029688,0.091347,-0.045674,0.089064,0,0.333418,