INSERT INTO programs (id, name, level, jurisdiction, city_scope, category, summary, benefit, eligibility_text, apply_url, source_url, source_label, source_snippet, interest_tags, audience_tags, housing_scope, min_age, max_age, income_targeted, requires_children, requires_disability, requires_veteran, requires_caregiver, embedding_json, last_checked, active) VALUES ('federal-child-tax-credit', 'Federal Child Tax Credit', 'federal', 'United States', 'sunnyvale,cupertino', 'family', 'The Child Tax Credit can reduce federal income tax for families with a qualifying child, and some families may receive a refundable Additional Child Tax Credit.', 'A federal tax credit for each qualifying child; the amount and refundable portion depend on the tax year and household circumstances.', 'Eligibility generally depends on the child''s age, relationship, residency, dependent status, Social Security number, and the taxpayer''s income and filing circumstances.', 'https://www.irs.gov/credits-deductions/individuals/child-tax-credit', 'https://www.irs.gov/credits-deductions/individuals/child-tax-credit', 'Internal Revenue Service', 'The IRS explains the Child Tax Credit, refundable Additional Child Tax Credit, qualifying-child rules, and how to claim the credit on a federal return.', 'child tax credit,tax credit,tax refund,children,family,dependent', 'children,family,parent', 'any', NULL, 16, 0, 1, 0, 0, 0, '[0,0,0.017313,-0.034627,0.559353,0,0.026636,-0.026636,0.043949,-0.05194,0,-0.053272,0,-0.017313,0.017313,-0.017313,0.053272,-0.017313,0,0,0,-0.034627,0,-0.017313,0.034627,0,0.097221,0,0.2304,-0.017313,0,0,0.026636,-0.017313,0.043949,-0.017313,0.05194,-0.053272,0.133179,0,0.026636,-0.079908,0.017313,0,0,-0.034627,0.034627,0,0.053272,0,0,0,0.078576,0,0,-0.017313,0,0,0.399538,-0.053272,0,0,0.10388,-0.05194,0,0,0,0,0.017313,0,0.034627,0,0,-0.043949,0.034627,-0.017313,0,0,0.026636,-0.05194,0.123857,0,0.079908,-0.043949,0,-0.017313,0,-0.069253,0.034627,-0.05194,0.026636,0,0,-0.203764,0.2