INSERT INTO programs (id, name, level, jurisdiction, city_scope, category, summary, benefit, eligibility_text, apply_url, source_url, source_label, source_snippet, interest_tags, audience_tags, housing_scope, min_age, max_age, income_targeted, requires_children, requires_disability, requires_veteran, requires_caregiver, embedding_json, last_checked, active) VALUES ('federal-child-dependent-care-credit', 'Federal Child and Dependent Care Credit', 'federal', 'United States', 'sunnyvale,cupertino', 'family', 'This federal credit may offset part of the cost of care that allows a taxpayer to work or look for work, including eligible child care and care for a spouse or dependent who cannot care for themselves.', 'A federal tax credit based on a percentage of eligible work-related care expenses, subject to annual limits and tax-year rules.', 'Generally requires earned income and qualifying work-related care expenses for a child under 13 or a spouse or dependent who cannot care for themselves; filing-status and care-provider rules apply.', 'https://www.irs.gov/publications/p503', 'https://www.irs.gov/publications/p503', 'Internal Revenue Service', 'IRS Publication 503 explains qualifying people, eligible care expenses, earned-income rules, expense limits, and Form 2441.', 'child care,daycare,dependent care,caregiver,tax credit,tax refund,work', 'children,family,parent,caregiver,worker', 'any', NULL, NULL, 0, 0, 0, 0, 0, '[0.076062,-0.029255,0,0,0.487092,0,0.067286,-0.019016,0.019016,0,0,0,0.019016,-0.077525,0,-0.096541,0.165289,0,0.096541,0,0.029255,0,0.029255,-0.057047,0.057047,0,0.165289,-0.019016,0.058509,-0.019016,0.019016,-0.057047,0,-0.058509,0.019016,-0.019016,0.134572,0,0.146274,-0.057047,0,-0.077525,0.058509,0,0.086301,0,0.019016,0,0.067286,0,0.019016,0,0.029255,-0.067286,0,0,0.125795,0,0.291085,-0.067286,0.067286,0,0.038031,0,0.057047,0,0,0,0.04827,-0.029255,0,0,0.019016,-0.038031,0.04827,-0.019016,0.437358,-0.04827,0.019016,-0.067286,0.175528,0,0.04827,-0.029255,0,-0.04827,0,-0.029255,0.038031,-0.019016,0,0,0.019016,-0.117019,0.165289,-0.263293,0.204783,0,0.038031,0,0.086301,-0.019016,0.04827,0,0.087764,-0.096541,0.04827,-0.029255,0,0,0,-0.029255,0.077525,0,0.019016,-0.038031,0.04827,0,0.057047,0,0.019016,-0.019016,0.019016,0,0.134572,-0.058509,0,0]', '2026-10-23', 1);
INSERT INTO programs (id, name, level, jurisdiction, city_scope, category, summary, benefit, eligibility_text, apply_url, source_url, source_label, source_snippet, interest_tags, audience_tags, housing_scope, min_age, max_age, income_targeted, requires_children, requires_disability, requires_veteran, requires_caregiver, embedding_json, last_checked, active) VALUES ('federal-earned-income-tax-credit', 'Federal Earned Income Tax Credit', 'federal', 'United States', 'sunnyvale,cupertino', 'family', 'The Earned Income Tax Credit is a refundable federal credit for eligible workers and families with low to moderate earned income, with or without qualifying children.', 'A refundable federal tax credit whose amount varies by earned income, filing status, and number of qualifying children.', 'Requires qualifying earned income and compliance with income, investment-income, filing-status, residency, identification-number, and qualifying-child rules that apply to the tax year.', 'https://www.irs.gov/credits-deductions/individuals/earned-income-tax-credit-eitc', 'https://www.irs.gov/credits-deductions/individuals/earned-income-tax-credit-eitc', 'Internal Revenue Service', 'The IRS provides current EITC rules, income limits, an eligibility assistant, and instructions for claiming the credit on a federal return.', 'earned income tax credit,eitc,tax credit,tax refund,income,work,family', 'worker,low income,family', 'any', NULL, NULL, 1, 0, 0, 0, 0, '[0.044026,-0.053365,0,-0.026683,0.533653,-0.017344,0,-0.026683,0,0,0,-0.053365,0.026683,-0.017344,0.034687,-0.017344,0.130745,-0.017344,0.017344,-0.017344,0.044026,-0.044026,0,0,0,0,0.097392,-0.017344,0.132079,0,0,0,0.070709,-0.017344,0,-0.034687,0.088053,-0.026683,0.106731,0,0,-0.114735,0.070709,0,0.053365,0,0.034687,0,0.106731,0,0,-0.017344,0.017344,0,0,0,0.017344,0,0.346875,-0.026683,0.017344,0,0.086719,0,0.017344,0,0,0,0.034687,0,0.052031,0,0.052031,-0.06137,0.017344,-0.017344,0,-0.017344,0,-0.017344,0,-0.017344,0.088053,0,0,-0.0266