INSERT INTO programs (id, name, level, jurisdiction, city_scope, category, summary, benefit, eligibility_text, apply_url, source_url, source_label, source_snippet, interest_tags, audience_tags, housing_scope, min_age, max_age, income_targeted, requires_children, requires_disability, requires_veteran, requires_caregiver, embedding_json, last_checked, active) VALUES ('california-child-dependent-care-credit', 'California Child and Dependent Care Expenses Credit', 'state', 'California', 'sunnyvale,cupertino', 'family', 'California may provide a state income-tax credit when a taxpayer pays for qualifying child or dependent care in California so they can work or look for work.', 'A nonrefundable California tax credit based on a percentage of eligible care expenses, subject to income and expense limits.', 'Generally requires earned income, federal adjusted gross income of $100,000 or less, California-provided care, and qualifying work-related care for a child under 13 or another qualifying person.', 'https://www.ftb.ca.gov/file/personal/credits/child-and-dependent-care-expenses-credit.html', 'https://www.ftb.ca.gov/file/personal/credits/child-and-dependent-care-expenses-credit.html', 'California Franchise Tax Board', 'The Franchise Tax Board explains eligibility, eligible expense limits, and how to claim the credit using FTB Form 3506.', 'child care,daycare,dependent care,caregiver,tax credit,tax refund,work', 'children,family,parent,caregiver,worker', 'any', NULL, NULL, 1, 0, 0, 0, 0, '[0.074697,0,0,0,0.540739,-0.02111,0.032477,0,0,0,0,0,0,-0.086064,0.053587,0,0.11854,-0.02111,0.107174,-0.02111,0.032477,-0.02111,0.053587,-0.053587,0.08444,-0.032477,0.053587,0,0.074697,-0.04222,0.032477,-0.02111,0,0,0.02111,0,0.053587,-0.02111,0.129907,-0.04222,0,-0.086064,0.02111,0,0.04222,0,0,0,0.11854,0,0,0,0.032477,-0.074697,0,-0.162384,0.107174,-0.02111,0.292291,-0.04222,0,0,0.08444,0,0.04222,0,0,0,0.095807,-0.032477,0,-0.064954,0,0,0,0,0.334511,-0.074697,0.02111,-0.074697,0.151017,0,0.053587,-0.02111,0,-0.032477,0,-0.032477,0.04222,-0.02111,0.02111,-0.02111,0.02111,-0.129907,0.259815,-0.292291,0.151017,0,0.02111,-0.02111,0.08444,-0.074697,0.086064,-0.032477,0.064954,-0.107174,0.02111,-0.032477,0,0,0,0,0.074697,-0.02111,0.02111,-0.04222,0.032477,0,0.053587,0,0.02111,-0.02111,0.06333,0,0.149393,-0.064954,0,-0.064954]', '2026-10-23', 1);
INSERT INTO programs (id, name, level, jurisdiction, city_scope, category, summary, benefit, eligibility_text, apply_url, source_url, source_label, source_snippet, interest_tags, audience_tags, housing_scope, min_age, max_age, income_targeted, requires_children, requires_disability, requires_veteran, requires_caregiver, embedding_json, last_checked, active) VALUES ('california-earned-income-tax-credit', 'California Earned Income Tax Credit', 'state', 'California', 'sunnyvale,cupertino', 'family', 'CalEITC is a refundable California tax credit for eligible low-income workers and families, including people who do not have a qualifying child.', 'Up to $3,756 for tax year 2025, depending on earned income and qualifying children; filing or amending a California return is required.', 'For eligible California workers and families with 2025 earned income and federal adjusted gross income below $32,901; age, residency, identification-number, filing, and dependent rules apply.', 'https://www.ftb.ca.gov/file/personal/credits/caleitc/', 'https://www.ftb.ca.gov/file/personal/credits/california-earned-income-Tax-credit.html', 'California Franchise Tax Board', 'The Franchise Tax Board states that eligible working Californians may claim CalEITC by filing a state return and FTB Form 3514.', 'california earned income tax credit,caleitc,tax credit,tax refund,income,work,family', 'worker,low income,family', 'any', NULL, NULL, 1, 0, 0, 0, 0, '[0,-0.06308,0,0,0.473102,-0.03154,0,-0.052041,0,0,0.03154,-0.03154,0,-0.061503,0.020501,-0.03154,0.176625,-0.020501,0.041002,-0.020501,0.03154,-0.083581,0.020501,0,0,-0.020501,0.03154,-0.020501,0.124584,-0.020501,0,-0.020501,0.09462,-0.041002,0,0,0.052041,-0.083581,0.261783,0,0.052041,-0.115121,0.020501,0,0.083581,0,0,0,0.06308,-0.020501,0,-0.041002,0.061503,0,0.020501,-0.157701,0.020501,-0.020501,0.315401,-0.093043,0,0,0.082004,-0.052041,0.06308,0,0,0,0.041002,0,0.020501,-0.06308,0.061503,-0.020501,0.041002,0,0,0,0.020501,0,0.126161,0,0.052041,0,0