INSERT INTO programs (id, name, level, jurisdiction, city_scope, category, summary, benefit, eligibility_text, apply_url, source_url, source_label, source_snippet, interest_tags, audience_tags, housing_scope, min_age, max_age, income_targeted, requires_children, requires_disability, requires_veteran, requires_caregiver, embedding_json, last_checked, active) VALUES ('california-young-child-tax-credit', 'California Young Child Tax Credit', 'state', 'California', 'sunnyvale,cupertino', 'family', 'The Young Child Tax Credit is a refundable California credit for eligible households with a qualifying child younger than six.', 'Up to $1,189 per eligible tax return for tax year 2025, which may provide cash back or reduce state tax owed.', 'Generally requires a qualifying child under age six and meeting CalEITC-related income, residency, filing, and identification-number rules; special rules allow some households with no earned income or a net loss.', 'https://www.ftb.ca.gov/file/personal/credits/young-child-tax-credit.html', 'https://www.ftb.ca.gov/file/personal/credits/young-child-tax-credit.html', 'California Franchise Tax Board', 'The Franchise Tax Board explains the refundable Young Child Tax Credit and how to claim it with FTB Form 3514.', 'young child tax credit,yctc,tax credit,tax refund,baby,toddler,children,family', 'children,family,parent,low income', 'any', NULL, 5, 1, 1, 0, 0, 0, '[0.054704,-0.028053,0,0,0.56107,0,0.028053,-0.028053,0,0,0.028053,-0.08416,0,-0.03647,0,-0.046288,0.102395,0,0.018235,0,0.03647,-0.064523,0,-0.018235,0,0,0.110811,-0.018235,0.08416,0,0.018235,0,0.074342,-0.018235,0.028053,0,0.074342,0,0.130449,0,0.03647,-0.102395,0,-0.056107,0,-0.018235,0,0,0.08416,0,0.046288,-0.018235,0.100993,0,0,-0.08416,0.028053,0,0.392749,0,0.054704,-0.072939,0.109409,-0.028053,0.028053,0,0,-0.08416,0,0,0,0,0.018235,0,0.03647,0,0.018235,-0.046288,0,-0.03647,0,-0.03647,0.12063,-0.018235,0,-0.028053,0,-0.054704,0.028053,0,0.018235,-0.028053,0.018235,-0.176737,0.3085