INSERT INTO programs (id, name, level, jurisdiction, city_scope, category, summary, benefit, eligibility_text, apply_url, source_url, source_label, source_snippet, interest_tags, audience_tags, housing_scope, min_age, max_age, income_targeted, requires_children, requires_disability, requires_veteran, requires_caregiver, embedding_json, last_checked, active) VALUES ('california-subsidized-child-care', 'California Subsidized Child Care', 'state', 'California', 'sunnyvale,cupertino', 'family', 'California supports voucher-based and center-based child-care programs that can help eligible families pay for care through CalWORKs and other subsidized child-care pathways.', 'Full or partial payment of eligible child-care costs through a voucher or a subsidized child-care provider, depending on the program and available space.', 'Programs use income or categorical eligibility plus a qualifying need for care, such as employment, education, training, seeking permanent housing, or child-protective circumstances; program availability and family fees vary.', 'https://www.cdss.ca.gov/inforesources/calworks-child-care/parent-information-and-resources', 'https://www.cdss.ca.gov/inforesources/child-care-and-development/child-care-and-development-programs', 'California Department of Social Services', 'CDSS describes California''s voucher-based and direct-service subsidized child-care programs and directs families to local resource-and-referral and alternative-payment agencies.', 'child care,childcare,daycare,preschool,voucher,work,education,family', 'children,family,parent,worker,student,low income', 'any', NULL, NULL, 1, 1, 0, 0, 0, '[0.028435,-0.115928,0,0,0.218732,-0.115928,0,-0.028435,0.085305,-0.043746,0,0,0,-0.072182,0.043746,-0.028435,0.087493,-0.072182,0,0,0,-0.115928,0.043746,-0.05687,0.100617,-0.131239,0.072182,0,0.072182,-0.028435,0,0,0.043746,-0.028435,0,-0.028435,0.129052,-0.072182,0.174986,-0.199046,0.115928,-0.349971,0.072182,0,0.072182,-0.05687,0.028435,-0.043746,0.0721